<template>
  <div class="page-heading"><div><h1 class="page-title">网咨设置</h1><p>在统一入口维护表单与列表字段、状态及标签；编码创建后不可修改。</p></div></div>
  <section class="content-panel"><el-tabs v-model="tab">
    <el-tab-pane label="表单字段与列表字段" name="fields"><div class="tab-toolbar"><p>固定必填字段不可关闭或删除；自定义字段有历史数据后仅停用。</p><el-button type="primary" @click="openField()">新增自定义字段</el-button></div><el-table :data="fields" v-loading="loading"><el-table-column prop="name" label="字段名称"/><el-table-column prop="code" label="字段编码"/><el-table-column prop="type" label="类型" width="100"/><el-table-column label="来源" width="90"><template #default="{row}"><el-tag :type="row.source==='FIXED'?'info':'success'">{{row.source==='FIXED'?'固定':'自定义'}}</el-tag></template></el-table-column><el-table-column label="必填/启用" width="130"><template #default="{row}">{{row.required?'必填':'选填'}} · {{row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column label="展示位置" min-width="180"><template #default="{row}">{{[row.showInForm&&'录单',row.showInDetail&&'详情',row.showInList&&'列表',row.filterable&&'筛选',row.exportable&&'导出'].filter(Boolean).join(' / ')||'—'}}</template></el-table-column><el-table-column prop="listWidth" label="列宽" width="80"/><el-table-column label="操作" width="160"><template #default="{row}"><div class="setting-actions"><el-button link type="primary" @click="openField(row)">设置</el-button><el-button v-if="row.source==='CUSTOM'" link type="danger" @click="removeField(row)">停用</el-button></div></template></el-table-column></el-table></el-tab-pane>
    <el-tab-pane label="状态管理" name="statuses"><div class="tab-toolbar"><p>完结和无效状态不会进入今日回访；已使用状态删除时自动改为停用。</p><el-button type="primary" @click="openStatus()">新增状态</el-button></div><el-table :data="statuses"><el-table-column prop="name" label="状态名称"/><el-table-column prop="code" label="编码"/><el-table-column label="颜色"><template #default="{row}"><span class="color-dot" :style="{background:row.color}"/>{{row.color}}</template></el-table-column><el-table-column label="分类"><template #default="{row}">{{categoryLabel(row.category)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><div class="setting-actions"><el-button link type="primary" @click="openStatus(row)">编辑</el-button><el-button link type="danger" @click="removeStatus(row)">删除/停用</el-button></div></template></el-table-column></el-table></el-tab-pane>
    <el-tab-pane label="标签管理" name="tags"><div class="tab-toolbar"><p>标签名称全局唯一；历史已使用标签停用后仍会显示。</p><el-button type="primary" @click="openTag()">新增标签</el-button></div><el-table :data="tags"><el-table-column prop="name" label="标签名称"/><el-table-column label="颜色"><template #default="{row}"><span class="color-dot" :style="{background:row.color}"/>{{row.color}}</template></el-table-column><el-table-column prop="sort" label="排序"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><div class="setting-actions"><el-button link type="primary" @click="openTag(row)">编辑</el-button><el-button link type="danger" @click="removeTag(row)">删除/停用</el-button></div></template></el-table-column></el-table></el-tab-pane>
  </el-tabs></section>

  <el-dialog v-model="fieldDialog" :title="fieldForm.id?'设置字段':'新增自定义字段'" width="720px"><el-form label-position="top" class="grid"><el-form-item label="字段名称" required><el-input v-model="fieldForm.name"/></el-form-item><el-form-item label="字段编码" required><el-input v-model="fieldForm.code" :disabled="Boolean(fieldForm.id)" placeholder="例如：consult_note"/></el-form-item><el-form-item label="字段类型" required><el-select v-model="fieldForm.type" :disabled="Boolean(fieldForm.id)"><el-option v-for="item in fieldTypes" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="列表标题"><el-input v-model="fieldForm.listTitle"/></el-form-item><el-form-item label="列表顺序"><el-input-number v-model="fieldForm.listOrder" :min="0"/></el-form-item><el-form-item label="列表列宽"><el-input-number v-model="fieldForm.listWidth" :min="60" :max="600"/></el-form-item><el-form-item v-if="['SINGLE','MULTI'].includes(fieldForm.type)" label="选项（每行一项）" class="full"><el-input v-model="fieldForm.optionText" type="textarea" :rows="5"/></el-form-item><el-form-item label="字段能力" class="full"><el-checkbox v-model="fieldForm.required">必填</el-checkbox><el-checkbox v-model="fieldForm.enabled">启用</el-checkbox><el-checkbox v-model="fieldForm.showInForm">录单显示</el-checkbox><el-checkbox v-model="fieldForm.showInDetail">详情显示</el-checkbox><el-checkbox v-model="fieldForm.showInList">默认列表显示</el-checkbox><el-checkbox v-model="fieldForm.filterable">支持筛选</el-checkbox><el-checkbox v-model="fieldForm.importable">支持导入</el-checkbox><el-checkbox v-model="fieldForm.exportable">允许导出</el-checkbox></el-form-item></el-form><template #footer><el-button @click="fieldDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveField">保存</el-button></template></el-dialog>
  <el-dialog v-model="statusDialog" :title="statusForm.id?'编辑状态':'新增状态'" width="560px"><el-form label-position="top" class="grid"><el-form-item label="状态名称"><el-input v-model="statusForm.name"/></el-form-item><el-form-item label="状态编码"><el-input v-model="statusForm.code" :disabled="Boolean(statusForm.id)"/></el-form-item><el-form-item label="状态分类"><el-select v-model="statusForm.category"><el-option label="进行中" value="IN_PROGRESS"/><el-option label="完结" value="COMPLETED"/><el-option label="无效" value="INVALID"/></el-select></el-form-item><el-form-item label="颜色"><el-color-picker v-model="statusForm.color"/></el-form-item><el-form-item label="排序"><el-input-number v-model="statusForm.sort" :min="0"/></el-form-item><el-form-item label="启用"><el-switch v-model="statusForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="statusDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveStatus">保存</el-button></template></el-dialog>
  <el-dialog v-model="tagDialog" :title="tagForm.id?'编辑标签':'新增标签'" width="520px"><el-form label-position="top"><el-form-item label="标签名称"><el-input v-model="tagForm.name"/></el-form-item><el-form-item label="标签颜色"><el-color-picker v-model="tagForm.color"/></el-form-item><el-form-item label="排序"><el-input-number v-model="tagForm.sort" :min="0"/></el-form-item><el-form-item label="启用"><el-switch v-model="tagForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="tagDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveTag">保存</el-button></template></el-dialog>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { createConsultationField,createConsultationStatus,createConsultationTag,deleteConsultationField,deleteConsultationStatus,deleteConsultationTag,getConsultationFields,getConsultationStatuses,getConsultationTags,updateConsultationField,updateConsultationStatus,updateConsultationTag,type ConsultationFieldItem,type ConsultationStatusItem,type ConsultationTagItem } from '../api/admin';
const tab=ref('fields'),loading=ref(false),saving=ref(false),fields=ref<ConsultationFieldItem[]>([]),statuses=ref<ConsultationStatusItem[]>([]),tags=ref<ConsultationTagItem[]>([]),fieldDialog=ref(false),statusDialog=ref(false),tagDialog=ref(false);const fieldTypes=[{value:'TEXT',label:'单行文本'},{value:'TEXTAREA',label:'多行文本'},{value:'SINGLE',label:'单选'},{value:'MULTI',label:'多选'},{value:'DATE',label:'日期'},{value:'DATETIME',label:'日期时间'},{value:'NUMBER',label:'数字'}];
const blankField=()=>({id:'',name:'',code:'',type:'TEXT',required:false,enabled:true,showInForm:true,showInDetail:true,showInList:false,filterable:false,exportable:false,importable:false,listTitle:'',listOrder:0,listWidth:140,optionText:'',source:'CUSTOM'});const fieldForm=reactive<any>(blankField());const statusForm=reactive<any>({id:'',name:'',code:'',color:'#457ea9',sort:0,enabled:true,category:'IN_PROGRESS'});const tagForm=reactive<any>({id:'',name:'',color:'#838e7c',sort:0,enabled:true});
async function load(){loading.value=true;try{[fields.value,statuses.value,tags.value]=await Promise.all([getConsultationFields(),getConsultationStatuses(),getConsultationTags()])}finally{loading.value=false}}function openField(row?:ConsultationFieldItem){Object.assign(fieldForm,blankField(),row||{}, {optionText:(row?.options||[]).join('\n')});fieldDialog.value=true}function openStatus(row?:ConsultationStatusItem){Object.assign(statusForm,{id:'',name:'',code:'',color:'#457ea9',sort:0,enabled:true,category:'IN_PROGRESS'},row||{});statusDialog.value=true}function openTag(row?:ConsultationTagItem){Object.assign(tagForm,{id:'',name:'',color:'#838e7c',sort:0,enabled:true},row||{});tagDialog.value=true}
async function saveField(){if(!fieldForm.name||!fieldForm.code)return ElMessage.warning('请填写字段名称和编码');saving.value=true;try{const payload={...fieldForm,options:fieldForm.optionText.split('\n').map((i:string)=>i.trim()).filter(Boolean)};delete payload.id;delete payload.optionText;delete payload.source;if(fieldForm.id)await updateConsultationField(fieldForm.id,payload);else await createConsultationField(payload);fieldDialog.value=false;ElMessage.success('字段设置已保存');await load()}finally{saving.value=false}}async function saveStatus(){saving.value=true;try{const p={...statusForm};delete p.id;if(statusForm.id)await updateConsultationStatus(statusForm.id,p);else await createConsultationStatus(p);statusDialog.value=false;await load()}finally{saving.value=false}}async function saveTag(){saving.value=true;try{const p={...tagForm};delete p.id;if(tagForm.id)await updateConsultationTag(tagForm.id,p);else await createConsultationTag(p);tagDialog.value=false;await load()}finally{saving.value=false}}
async function removeField(row:ConsultationFieldItem){await ElMessageBox.confirm('自定义字段将停用，历史数据仍保留。','停用字段',{type:'warning'});await deleteConsultationField(row.id);load()}async function removeStatus(row:ConsultationStatusItem){await ElMessageBox.confirm('已使用状态会改为停用，历史数据不会修改。','删除或停用状态',{type:'warning'});await deleteConsultationStatus(row.id);load()}async function removeTag(row:ConsultationTagItem){await ElMessageBox.confirm('已使用标签会改为停用，历史数据仍显示。','删除或停用标签',{type:'warning'});await deleteConsultationTag(row.id);load()}function categoryLabel(v:string){return v==='COMPLETED'?'完结':v==='INVALID'?'无效':'进行中'}onMounted(load);
</script>
<style scoped>.page-heading{margin-bottom:16px}.page-heading p,.tab-toolbar p{color:var(--admin-text-muted)}.tab-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:12px}.setting-actions{display:flex;align-items:center;justify-content:center;flex-wrap:nowrap;gap:8px;white-space:nowrap}.setting-actions :deep(.el-button){flex:0 0 auto;margin:0;padding:4px 3px;white-space:nowrap}.color-dot{display:inline-block;width:14px;height:14px;margin-right:8px;border-radius:50%;vertical-align:-2px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 14px}.grid :deep(.el-select){width:100%}.full{grid-column:1/-1}@media(max-width:700px){.tab-toolbar{align-items:flex-start;flex-direction:column}.grid{grid-template-columns:1fr}.full{grid-column:auto}}</style>
